if (!options.eventState) {
	options.eventState = aras.evalMethod('cui_reinit_calc_tearoff_states');
}
const { itemTypeName, itemId } = options;
const hidden = !options.eventState.discussionEnabled;
const disabled = ArasModules.item.isNew(itemTypeName, itemId);
return {
  hidden,
  disabled
};
